// ============================================================
// WF1 - Node Code: susun response pencarian resi.
// [ENHANCEMENT 2026-07-06] Timeline (riwayat) dibangun dari sheet
//   Log_History (bukan lagi kolom JSON). Snapshot resi diambil dari
//   sheet Tracking; bila tidak ada, fallback ke sheet Archive.
//   MODE A (ada param resi): cari snapshot + rakit riwayat per resi.
//   MODE B (param resi kosong): semua resi Tracking dgn Timestamp_Update
//     <= 30 hari terakhir (maks 100, terbaru dulu).
// ============================================================

const rowsTracking = $items('Baca Sheet Tracking').map(i => i.json)
  .filter(r => String(r.No_Resi || '').trim() !== '');
const rowsArchive = $items('Baca Sheet Archive').map(i => i.json)
  .filter(r => String(r.No_Resi || '').trim() !== '');
const rowsLog = $items('Baca Sheet Log_History').map(i => i.json)
  .filter(r => String(r.No_Resi || '').trim() !== '');

// Query dari webhook.
const webhookData = $items('Webhook GET tracking-get')[0].json;
const query = webhookData.query || {};
const resiParamRaw = query.resi || '';
const daftarResi = String(resiParamRaw)
  .split(',').map(r => r.trim().toUpperCase()).filter(r => r.length > 0);

// Kelompokkan Log_History per No_Resi (uppercase), urut waktu MENAIK.
const logByResi = {};
for (const r of rowsLog) {
  const key = String(r.No_Resi || '').trim().toUpperCase();
  if (!key) continue;
  if (!logByResi[key]) logByResi[key] = [];
  logByResi[key].push({
    waktu: r.Timestamp_Update || '',
    status: r.Status || '',
    lokasi: r.Lokasi || '',
    admin: r.Nama_Admin || ''
  });
}
for (const k in logByResi) {
  logByResi[k].sort((a, b) => {
    const ta = Date.parse(a.waktu), tb = Date.parse(b.waktu);
    if (isNaN(ta) && isNaN(tb)) return 0;
    if (isNaN(ta)) return -1;
    if (isNaN(tb)) return 1;
    return ta - tb;
  });
}

// Bangun entri response dari satu snapshot row + riwayat dari Log_History.
function buildEntri(snapshot, resiKey, dariArsip) {
  const riwayat = logByResi[resiKey] ? logByResi[resiKey].slice() : [];
  const entri = {
    no_resi: String(snapshot.No_Resi || resiKey),
    found: true,
    status_terakhir: snapshot.Status_Terakhir || '',
    timestamp_update: snapshot.Timestamp_Update || '',
    riwayat: riwayat
  };
  if (dariArsip) entri.arsip = true;
  return entri;
}

// ── MODE B: tanpa param resi → semua resi Tracking 30 hari terakhir ──
if (daftarResi.length === 0) {
  const now = Date.now();
  const AMBANG_MS = 30 * 24 * 60 * 60 * 1000;
  const hasil = [];
  for (const row of rowsTracking) {
    const key = String(row.No_Resi || '').trim().toUpperCase();
    const t = Date.parse(row.Timestamp_Update);
    if (isNaN(t) || (now - t) > AMBANG_MS) continue;
    hasil.push(buildEntri(row, key, false));
  }
  hasil.sort((a, b) => Date.parse(b.timestamp_update) - Date.parse(a.timestamp_update));
  const dibatasi = hasil.slice(0, 100);
  return [{ json: { results: dibatasi, data: dibatasi, total: dibatasi.length, cakupan: 'terbaru-30-hari' } }];
}

// ── MODE A: pencarian per resi ──
const indexTracking = {};
for (const row of rowsTracking) {
  const key = String(row.No_Resi || '').trim().toUpperCase();
  if (key) indexTracking[key] = row;
}
const indexArsip = {};
for (const row of rowsArchive) {
  const key = String(row.No_Resi || '').trim().toUpperCase();
  if (key) indexArsip[key] = row;
}

const hasil = [];
for (const resi of daftarResi) {
  if (indexTracking[resi]) {
    hasil.push(buildEntri(indexTracking[resi], resi, false));
    continue;
  }
  if (indexArsip[resi]) {
    hasil.push(buildEntri(indexArsip[resi], resi, true));
    continue;
  }
  hasil.push({ no_resi: resi, found: false });
}

return [{ json: { results: hasil, data: hasil, total: hasil.length } }];
